def vowel_back(s):
    vowels = "aeiou"
    exceptions = {'c': -1, 'o': -1, 'd': -3, 'e': -4}

    def transform(char):
        if char in exceptions:
            shift = exceptions[char]
        elif char in vowels:
            shift = -5
        else:
            shift = 9

        original_ord = ord(char) - ord('a')
        new_ord = (original_ord + shift) % 26
        new_char = chr(new_ord + ord('a'))

        if new_char in ['c', 'o', 'd', 'e']:
            return char
        return new_char

    return ''.join(transform(c) for c in s)
